30	rbtree_t *rb_create(rb_value_free_fn value_free) {
31	    rbtree_t *t = rb_malloc(sizeof *t);
32	    if (t == NULL) return NULL;
33	    t->root = NULL;
34	    t->size = 0;
35	    t->value_free = value_free;
36	    return t;
37	}
