39	void *rb_find(const rbtree_t *t, const char *key) {
40	    struct rb_node *cur = t->root;
41	    while (cur != NULL) {
42	        int cmp = strcmp(key, cur->key);
43	        if (cmp == 0) return cur->value;
44	        cur = (cmp < 0) ? cur->left : cur->right;
45	    }
46	    return NULL;
47	}
