49	/* Standard BST rotation, extended to keep parent pointers and t->root
50	 * correct — rotations own root maintenance, not rb_validate. */
51	static void rotate_left(rbtree_t *t, struct rb_node *x) {
52	    struct rb_node *y = x->right;
53	    x->right = y->left;
54	    if (y->left != NULL) y->left->parent = x;
55	    y->parent = x->parent;
56	    if (x->parent == NULL)        t->root = y;
57	    else if (x == x->parent->left) x->parent->left = y;
58	    else                            x->parent->right = y;
59	    y->left = x;
60	    x->parent = y;
61	}
62	
63	static void rotate_right(rbtree_t *t, struct rb_node *x) {
64	    struct rb_node *y = x->left;
65	    x->left = y->right;
66	    if (y->right != NULL) y->right->parent = x;
67	    y->parent = x->parent;
68	    if (x->parent == NULL)         t->root = y;
69	    else if (x == x->parent->right) x->parent->right = y;
70	    else                             x->parent->left = y;
71	    y->right = x;
72	    x->parent = y;
73	}
