75	static void insert_fixup(rbtree_t *t, struct rb_node *z) {
76	    /* Invariant: z is red. Loop while z's parent is also red (the only
77	     * possible violation after a plain BST insert of a red node). */
78	    while (is_red(z->parent)) {
79	        struct rb_node *parent = z->parent;
80	        struct rb_node *grandparent = parent->parent;
81	        if (parent == grandparent->left) {
82	            struct rb_node *uncle = grandparent->right;
83	            if (is_red(uncle)) {
84	                parent->color = BLACK;
85	                uncle->color = BLACK;
86	                grandparent->color = RED;
87	                z = grandparent;
88	            } else {
89	                if (z == parent->right) {
90	                    z = parent;
91	                    rotate_left(t, z);
92	                    parent = z->parent;
93	                }
94	                parent->color = BLACK;
95	                grandparent->color = RED;
96	                rotate_right(t, grandparent);
97	            }
98	        } else {
99	            struct rb_node *uncle = grandparent->left;
100	            if (is_red(uncle)) {
101	                parent->color = BLACK;
102	                uncle->color = BLACK;
103	                grandparent->color = RED;
104	                z = grandparent;
105	            } else {
106	                if (z == parent->left) {
107	                    z = parent;
108	                    rotate_right(t, z);
109	                    parent = z->parent;
110	                }
111	                parent->color = BLACK;
112	                grandparent->color = RED;
113	                rotate_left(t, grandparent);
114	            }
115	        }
116	    }
117	    t->root->color = BLACK;
118	}
