120	int rb_insert(rbtree_t *t, const char *key, void *value) {
121	    struct rb_node *parent = NULL;
122	    struct rb_node *cur = t->root;
123	    int cmp = 0;
124	    while (cur != NULL) {
125	        cmp = strcmp(key, cur->key);
126	        if (cmp == 0) {
127	            if (t->value_free) t->value_free(cur->value);
128	            cur->value = value;
129	            return 0;
130	        }
131	        parent = cur;
132	        cur = (cmp < 0) ? cur->left : cur->right;
133	    }
134	
135	    struct rb_node *n = rb_malloc(sizeof *n);
136	    if (n == NULL) return -1;
137	
138	    size_t keylen = strlen(key) + 1;
139	    n->key = rb_malloc(keylen);
140	    if (n->key == NULL) {
141	        rb_free(n);
142	        return -1;
143	    }
144	    memcpy(n->key, key, keylen);
145	
146	    n->value = value;
147	    n->color = RED;
148	    n->left = n->right = NULL;
149	    n->parent = parent;
150	
151	    if (parent == NULL)      t->root = n;
152	    else if (cmp < 0)        parent->left = n;
153	    else                     parent->right = n;
154	
155	    insert_fixup(t, n);
156	    t->size++;
157	    return 0;
158	}
