160	static struct rb_node *find_node(const rbtree_t *t, const char *key) {
161	    struct rb_node *cur = t->root;
162	    while (cur != NULL) {
163	        int cmp = strcmp(key, cur->key);
164	        if (cmp == 0) return cur;
165	        cur = (cmp < 0) ? cur->left : cur->right;
166	    }
167	    return NULL;
168	}
