175	/* Puts v in u's slot (u->parent, or t->root) -- the only place delete
176	 * touches t->root or reparents a node, mirroring the rotations. */
177	static void transplant(rbtree_t *t, struct rb_node *u, struct rb_node *v) {
178	    if (v != NULL) v->parent = u->parent;
179	    if (u->parent == NULL)         t->root = v;
180	    else if (u == u->parent->left) u->parent->left = v;
181	    else                            u->parent->right = v;
182	}
