184	/* x may be NULL (NIL); since NULL can't carry its own parent pointer,
185	 * (parent, x) is threaded through the loop as an explicit pair instead
186	 * of ever reading x->parent -- see NOTES.md's devlog on why this tree
187	 * has no shared sentinel. */
188	static void delete_fixup(rbtree_t *t, struct rb_node *parent, struct rb_node *x) {
189	    while (parent != NULL && is_black(x)) {
190	        if (x == parent->left) {
191	            struct rb_node *sib = parent->right;
192	            if (is_red(sib)) {                     /* Case 5: sibling red */
193	                sib->color = BLACK;
194	                parent->color = RED;
195	                rotate_left(t, parent);
196	                sib = parent->right;
197	            }
198	            if (is_black(sib->left) && is_black(sib->right)) { /* Case 3: both nephews black */
199	                sib->color = RED;
200	                x = parent;
201	                parent = x->parent;
202	            } else {
203	                if (is_black(sib->right)) {         /* near red / far black: convert first */
204	                    if (sib->left != NULL) sib->left->color = BLACK;
205	                    sib->color = RED;
206	                    rotate_right(t, sib);
207	                    sib = parent->right;
208	                }
209	                sib->color = parent->color;         /* Case 4: far nephew red, terminal */
210	                parent->color = BLACK;
211	                if (sib->right != NULL) sib->right->color = BLACK;
212	                rotate_left(t, parent);
213	                return;
214	            }
215	        } else {
216	            /* exact mirror: left/right swapped, rotate_right/rotate_left swapped */
217	            struct rb_node *sib = parent->left;
218	            if (is_red(sib)) {
219	                sib->color = BLACK;
220	                parent->color = RED;
221	                rotate_right(t, parent);
222	                sib = parent->left;
223	            }
224	            if (is_black(sib->left) && is_black(sib->right)) {
225	                sib->color = RED;
226	                x = parent;
227	                parent = x->parent;
228	            } else {
229	                if (is_black(sib->left)) {
230	                    if (sib->right != NULL) sib->right->color = BLACK;
231	                    sib->color = RED;
232	                    rotate_left(t, sib);
233	                    sib = parent->left;
234	                }
235	                sib->color = parent->color;
236	                parent->color = BLACK;
237	                if (sib->left != NULL) sib->left->color = BLACK;
238	                rotate_right(t, parent);
239	                return;
240	            }
241	        }
242	    }
243	    if (x != NULL) x->color = BLACK;
244	}
245	
246	int rb_delete(rbtree_t *t, const char *key) {
247	    struct rb_node *z = find_node(t, key);
248	    if (z == NULL) return -1;
249	
250	    struct rb_node *n;
251	    bool free_own_payload = true;
252	
253	    if (z->left != NULL && z->right != NULL) {
254	        struct rb_node *y = tree_min(z->right);
255	        rb_free(z->key);
256	        if (t->value_free) t->value_free(z->value);
257	        z->key = y->key;
258	        z->value = y->value;
259	        n = y;
260	        free_own_payload = false;
261	    } else {
262	        n = z;
263	    }
264	
265	    struct rb_node *child = (n->left != NULL) ? n->left : n->right;
266	    bool n_was_black = is_black(n);
267	    transplant(t, n, child);
268	
269	    if (n_was_black) {
270	        if (child != NULL) {
271	            child->color = BLACK;             /* STEP1: absorbs the debt locally */
272	        } else {
273	            delete_fixup(t, n->parent, NULL); /* STEP2: only after transplant has run */
274	        }
275	    }
276	
277	    if (free_own_payload) {
278	        rb_free(n->key);
279	        if (t->value_free) t->value_free(n->value);
280	    }
281	    rb_free(n);
282	    t->size--;
283	    return 0;
284	}
285	
286	size_t rb_size(const rbtree_t *t) {
287	    return t->size;
288	}
289	
290	static void foreach_inorder(const struct rb_node *n,
291	                             void (*fn)(const char *, void *, void *), void *ctx) {
292	    if (n == NULL) return;
293	    foreach_inorder(n->left, fn, ctx);
294	    fn(n->key, n->value, ctx);
295	    foreach_inorder(n->right, fn, ctx);
296	}
297	
298	void rb_foreach(const rbtree_t *t,
299	                void (*fn)(const char *key, void *value, void *ctx), void *ctx) {
300	    foreach_inorder(t->root, fn, ctx);
301	}
302	
303	struct validate_state {
304	    const char *prev_key;
305	    bool        order_ok;
306	    size_t      count;
307	};
308	
309	static void validate_walk(const struct rb_node *n, struct validate_state *st) {
310	    if (n == NULL) return;
311	    validate_walk(n->left, st);
312	    if (st->prev_key != NULL && strcmp(st->prev_key, n->key) >= 0) {
313	        st->order_ok = false;
314	    }
315	    st->prev_key = n->key;
316	    st->count++;
317	    validate_walk(n->right, st);
318	}
319	
320	static bool has_red_red(const struct rb_node *n) {
321	    if (n == NULL) return false;
322	    if (is_red(n) && (is_red(n->left) || is_red(n->right))) return true;
323	    return has_red_red(n->left) || has_red_red(n->right);
324	}
325	
326	/* Returns the subtree's black-height, or -1 if any root-to-NIL path within it
327	 * has already been found to disagree with another. NULL (NIL) contributes a
328	 * black-height of 1 by convention; a black node adds 1 on top of its children's
329	 * (equal) black-height. */
330	static int black_height(const struct rb_node *n) {
331	    if (n == NULL) return 1;
332	    int lh = black_height(n->left);
333	    if (lh == -1) return -1;
334	    int rh = black_height(n->right);
335	    if (rh == -1) return -1;
336	    if (lh != rh) return -1;
337	    return lh + (is_black(n) ? 1 : 0);
338	}
339	
340	int rb_validate(const rbtree_t *t) {
341	    if (is_red(t->root)) {
342	        fprintf(stderr, "rb_validate: invariant 1 violated (root is red)\n");
343	        return 1;
344	    }
345	    if (has_red_red(t->root)) {
346	        fprintf(stderr, "rb_validate: invariant 2 violated "
347	                         "(a red node has a red child)\n");
348	        return 2;
349	    }
350	    if (black_height(t->root) == -1) {
351	        fprintf(stderr, "rb_validate: invariant 3 violated "
352	                         "(root-to-NIL paths have differing black-height)\n");
353	        return 3;
354	    }
355	
356	    struct validate_state st = { .prev_key = NULL, .order_ok = true, .count = 0 };
357	    validate_walk(t->root, &st);
358	
359	    if (!st.order_ok) {
360	        fprintf(stderr, "rb_validate: invariant 4 violated "
361	                         "(in-order keys not strictly increasing under strcmp)\n");
362	        return 4;
363	    }
364	    if (st.count != t->size) {
365	        fprintf(stderr, "rb_validate: invariant 5 violated "
366	                         "(rb_size=%zu, actual node count=%zu)\n", t->size, st.count);
367	        return 5;
368	    }
369	    return 0;
370	}
371	
372	void rb_destroy(rbtree_t *t) {
373	    if (t == NULL) return;
374	    struct rb_node *cur = t->root;
375	    while (cur != NULL) {
376	        struct rb_node *next;
377	        if (cur->left == NULL) {
378	            next = cur->right;
379	            rb_free(cur->key);
380	            if (t->value_free) t->value_free(cur->value);
381	            rb_free(cur);
382	        } else {
383	            struct rb_node *left = cur->left;
384	            cur->left = left->right;
385	            left->right = cur;
386	            next = left; /* re-enter the loop rooted at the promoted node */
387	        }
388	        cur = next;
389	    }
390	    rb_free(t);
391	}
