172	static void test_insert_ascending_triggers_rr_rotation(void) {
173	    /* a < b < c inserted in ascending order forces the RR straight-line case
174	     * at the root: c (red) under b (red) under a (root, black), uncle NIL.
175	     * A left rotation at a must promote b to root. If the rotation forgets to
176	     * update t->root, rb_find would search from the stale (demoted) root and
177	     * silently miss keys — the stale-root regression. */
178	    rbtree_t *t = rb_create(NULL);
179	    int va = 1, vb = 2, vc = 3;
180	    check(rb_insert(t, "a", &va) == 0, "insert a");
181	    check(rb_insert(t, "b", &vb) == 0, "insert b");
182	    check(rb_insert(t, "c", &vc) == 0, "insert c (triggers RR rotation at root)");
183	    check(rb_find(t, "a") == &va, "find a after RR rotation");
184	    check(rb_find(t, "b") == &vb, "find b after RR rotation");
185	    check(rb_find(t, "c") == &vc, "find c after RR rotation");
186	    check(rb_size(t) == 3, "size is 3 after RR-triggering inserts");
187	    check(rb_validate(t) == 0, "validate passes after RR rotation");
188	    struct order_ctx ctx = { .count = 0 };
189	    rb_foreach(t, collect_key, &ctx);
190	    check(ctx.count == 3 && strcmp(ctx.keys[0], "a") == 0 &&
191	          strcmp(ctx.keys[1], "b") == 0 && strcmp(ctx.keys[2], "c") == 0,
192	          "foreach still in order after RR rotation");
193	    rb_destroy(t);
194	}
