312	/* ---- rb_delete: table-driven cases ----
313	 * Each case builds a tree via a fixed insertion sequence (chosen so the
314	 * insertion fixup produces the exact structural situation named), deletes
315	 * one key, then asserts rb_delete's return code, rb_size, rb_validate, that
316	 * the deleted key is gone, and that every surviving key is still findable.
317	 * Mirrored cases are literal left/right mirrors of their sibling case
318	 * (mirrored keys), per NOTES.md's decision tree and the spec's explicit
319	 * call-out that the mirror is "the half people forget."
320	 */
321	struct delete_case {
322	    const char *name;
323	    const char *insert_keys[TEST_MAX_KEYS];
324	    int         insert_count;
325	    const char *delete_key;
326	};
327	
328	static const struct delete_case delete_cases[] = {
329	    /* Red leaf: with keys b,a,c inserted, a and c end up red leaf children
330	     * of black root b. Deleting a red leaf needs no fixup at all. */
331	    { "delete red leaf", { "b", "a", "c" }, 3, "a" },
332	    { "delete red leaf (mirror)", { "b", "a", "c" }, 3, "c" },
333	
334	    /* Black leaf with red sibling (verified against an instrumented scratch
335	     * build that dumps real node colors -- an earlier candidate sequence
336	     * looked right by hand-simulation but actually produced a BLACK sibling
337	     * with red nephews, i.e. Case 4, not this Case 5):
338	     * c,b,d,f,g,l,n inserted, then delete b: b ends up a black leaf whose
339	     * sibling f is genuinely RED (f's children d is a black leaf, l is
340	     * black with red children g,n). Deleting b forces Case 5 (red sibling
341	     * rotated up over the parent, colors swapped, then the loop re-examines
342	     * the new -- now black -- sibling). */
343	    { "delete black leaf with red sibling",
344	      { "c", "b", "d", "f", "g", "l", "n" }, 7, "b" },
345	    /* Mirror: p,n,l,k,c,i,e inserted, then delete p: p is a black leaf
346	     * whose sibling k is RED, but on the LEFT this time, forcing the
347	     * mirrored (right) rotation direction. */
348	    { "delete black leaf with red sibling (mirror)",
349	      { "p", "n", "l", "k", "c", "i", "e" }, 7, "p" },
350	
351	    /* Node with two children: root has two children; delete the root itself
352	     * so the successor-splice path is exercised on the two-children case
353	     * generally (also doubles as the "root deletion" requirement). */
354	    { "delete node with two children (root)",
355	      { "d", "b", "f", "a", "c", "e", "g" }, 7, "d" },
356	    { "delete node with two children (non-root)",
357	      { "d", "b", "f", "a", "c", "e", "g" }, 7, "f" },
358	
359	    /* Root deletion, single node: the only node in the tree is the root. */
360	    { "delete root (single node tree)", { "only" }, 1, "only" },
361	
362	    /* delete_fixup Case 4, far nephew red directly (no near-red conversion
363	     * rotation needed): d,b,f,a,c,e,g,h inserted, then delete e. e is a black
