473	     *   iter3: x=056,   parent=048(R) -> Case 4 mirror (sib=040) -> TERMINAL
474	     * rb_validate passes before/after, rb_delete returns 0. */
475	    { "delete Case 3b (both nephews black, parent black -- multi-level climb, mirror)",
476	      { "059","058","042","040","029","030","002","024","034","006",
477	        "012","023","020","031","036","056","007","048","004","001",
478	        "011","057","054","051","033","009","005","010","052","050",
479	        "037","041","043","046","035","047","044","039" },
480	      38, "059" },
481	
482	    /* Black node with exactly one (red) child: b inserted then a inserted
483	     * descending leaves b black with a single red left child a (no fixup
484	     * needed for 2 nodes -- b stays black, a is red). Deleting b splices
485	     * a into its place. */
486	    { "delete black node with one red child (left)",
487	      { "b", "a" }, 2, "b" },
488	    { "delete black node with one red child (right, mirror)",
489	      { "a", "b" }, 2, "a" },
490	};
491	
492	static void run_delete_case(const struct delete_case *c) {
493	    rbtree_t *t = rb_create(NULL);
494	    int values[TEST_MAX_KEYS] = {0};
495	    char msg[256];
496	
497	    for (int i = 0; i < c->insert_count; i++) {
498	        snprintf(msg, sizeof msg, "[%s] insert %s", c->name, c->insert_keys[i]);
499	        check(rb_insert(t, c->insert_keys[i], &values[i]) == 0, msg);
500	    }
501	
502	    snprintf(msg, sizeof msg, "[%s] rb_delete(%s) returns 0", c->name, c->delete_key);
503	    check(rb_delete(t, c->delete_key) == 0, msg);
504	
505	    snprintf(msg, sizeof msg, "[%s] size decremented after delete", c->name);
506	    check(rb_size(t) == (size_t)(c->insert_count - 1), msg);
507	
508	    snprintf(msg, sizeof msg, "[%s] rb_validate passes after delete", c->name);
509	    check(rb_validate(t) == 0, msg);
510	
511	    snprintf(msg, sizeof msg, "[%s] deleted key %s no longer found", c->name, c->delete_key);
512	    check(rb_find(t, c->delete_key) == NULL, msg);
513	
514	    for (int i = 0; i < c->insert_count; i++) {
515	        if (strcmp(c->insert_keys[i], c->delete_key) == 0) continue;
516	        snprintf(msg, sizeof msg, "[%s] surviving key %s still found", c->name, c->insert_keys[i]);
517	        check(rb_find(t, c->insert_keys[i]) != NULL, msg);
518	    }
519	
520	    rb_destroy(t);
521	}
522	
523	static void test_delete_table_driven(void) {
524	    size_t n = sizeof delete_cases / sizeof delete_cases[0];
525	    for (size_t i = 0; i < n; i++) run_delete_case(&delete_cases[i]);
526	}
527	
528	static void test_delete_missing_key_returns_error(void) {
529	    rbtree_t *t = rb_create(NULL);
530	    int value = 1;
531	    check(rb_insert(t, "apple", &value) == 0, "insert apple for missing-key delete test");
532	    check(rb_delete(t, "banana") == -1, "rb_delete on absent key returns -1");
533	    check(rb_size(t) == 1, "size unchanged after failed delete");
534	    check(rb_validate(t) == 0, "validate still passes after failed delete");
535	    rb_destroy(t);
536	}
