538	static void test_delete_frees_value(void) {
539	    free_count = 0;
540	    rbtree_t *t = rb_create(counting_free);
541	    check(rb_insert(t, "apple", make_int(1)) == 0, "insert apple with heap value");
542	    check(rb_delete(t, "apple") == 0, "delete apple");
543	    check(free_count == 1, "value_free called exactly once on delete");
544	    check(rb_size(t) == 0, "size is 0 after deleting only node");
545	    rb_destroy(t);
546	}
